import { readFileSync } from "fs";

const lines = readFileSync(0, "utf8").trim().split("\n");
const [n, m] = lines[0].split(" ").map(Number);
const graph: [number, number][][] = Array.from({ length: n + 1 }, () => []);
for (let i = 1; i <= m; i++) {
  const [a, b, c] = lines[i].split(" ").map(Number);
  graph[a].push([b, c]);
}

// 距離が小さい順に取り出す二分ヒープ（要素は [距離, 頂点]）
const heap: [number, number][] = [];
function push(item: [number, number]): void {
  heap.push(item);
  let i = heap.length - 1;
  while (i > 0) {
    const p = (i - 1) >> 1;
    if (heap[p][0] <= heap[i][0]) break;
    [heap[p], heap[i]] = [heap[i], heap[p]];
    i = p;
  }
}
function pop(): [number, number] {
  const top = heap[0];
  const last = heap.pop()!;
  if (heap.length > 0) {
    heap[0] = last;
    let i = 0;
    for (;;) {
      const l = 2 * i + 1;
      const r = l + 1;
      let min = i;
      if (l < heap.length && heap[l][0] < heap[min][0]) min = l;
      if (r < heap.length && heap[r][0] < heap[min][0]) min = r;
      if (min === i) break;
      [heap[min], heap[i]] = [heap[i], heap[min]];
      i = min;
    }
  }
  return top;
}

const dist = new Array(n + 1).fill(Infinity);
dist[1] = 0;
push([0, 1]);
while (heap.length > 0) {
  const [d, v] = pop();
  if (d > dist[v]) continue; // すでにより短い距離で確定している
  for (const [to, cost] of graph[v]) {
    if (d + cost < dist[to]) {
      dist[to] = d + cost;
      push([dist[to], to]);
    }
  }
}
console.log(dist.slice(1).map((d) => (d === Infinity ? -1 : d)).join("\n"));
